// std::unique_ptr (Exclusive Ownership)
std::unique_ptr<int> up1(new int(10));
auto up2 = std::make_unique<float>(3.14f);

// Ownership transfer
auto up3 = std::move(up1);
// up1 is now null

// Custom deleter (e.g., file handle)
struct FileCloser { void operator()(FILE* f) const { fclose(f); } };
std::unique_ptr<FILE, FileCloser> log;

// std::shared_ptr (Shared Ownership, Reference Counting)
std::shared_ptr<int> sp1 = std::make_shared<int>(42);
std::shared_ptr<int> sp2 = sp1; // Increment ref count

// Get raw pointer (use sparingly)
int* raw_ptr = sp1.get();

// Reference count check
long count = sp1.use_count(); // 2

// std::weak_ptr (Non-owning observer, break cycles)
std::weak_ptr<int> wp = sp1;

// Access resource safely
if (auto shared = wp.lock()) {
    // Resource still exists
} else {
    // Resource freed
}
